def validate_isbn10(code: str) -> bool:
    """Return whether *code* is a valid ISBN-10, allowing hyphens and spaces."""
    cleaned = code.replace("-", "").replace(" ", "")
    if len(cleaned) != 10:
        return False
    if not all("0" <= char <= "9" for char in cleaned[:9]):
        return False
    check = cleaned[9]
    if check in "Xx":
        last_value = 10
    elif "0" <= check <= "9":
        last_value = ord(check) - ord("0")
    else:
        return False
    total = sum((ord(char) - ord("0")) * (10 - i) for i, char in enumerate(cleaned[:9]))
    total += last_value
    return total % 11 == 0

