def caesar_shift(text: str, shift: int) -> str:
    """Shift ASCII letters by ``shift`` positions, preserving case and others."""
    offset = shift % 26
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            result.append(chr((ord(char) - ord('a') + offset) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            result.append(chr((ord(char) - ord('A') + offset) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

