def balanced_brackets(text: str) -> bool:
    """Return whether all bracket characters in *text* are properly nested."""
    opening = {"(": ")", "[": "]", "{": "}"}
    closing = set(opening.values())
    stack = []
    for char in text:
        if char in opening:
            stack.append(opening[char])
        elif char in closing:
            if not stack or stack.pop() != char:
                return False
    return not stack

