    """Return distinct lowercase hashtag bodies in order of occurrence."""
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_")
    result = []
    seen = set()
    i = 0
    n = len(text)
    while i < n:
        if text[i] == "#" and i + 1 < n and text[i + 1] in allowed:
            j = i + 1
            while j < n and text[j] in allowed:
